create table if not exists public.structured_exams(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,library_item_id uuid references public.library_items(id) on delete set null,title text not null,duration_minutes integer not null default 180,verified_at timestamptz,created_at timestamptz not null default now());create table if not exists public.exam_questions(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,exam_id uuid not null references public.structured_exams(id) on delete cascade,question_number integer not null,prompt text not null,choices jsonb not null default '[]'::jsonb,correct_key text,source_page integer,confidence integer not null default 0,position integer not null,area_key text,topic_slug text,unique(exam_id,position));create table if not exists public.exam_attempts(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,exam_id uuid not null references public.structured_exams(id) on delete cascade,mode text not null check(mode in ('practice','simulation')),started_at timestamptz not null,submitted_at timestamptz,answers jsonb not null default '{}'::jsonb,flagged jsonb not null default '[]'::jsonb,current_index integer not null default 0,duration_minutes integer not null,question_times_sec jsonb not null default '{}'::jsonb);alter table public.structured_exams enable row level security;alter table public.exam_questions enable row level security;alter table public.exam_attempts enable row level security;create policy "structured_exams_own" on public.structured_exams for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "exam_questions_own" on public.exam_questions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "exam_attempts_own" on public.exam_attempts for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
